def workflow_progress(payload):
    steps=WORKFLOWS.get(payload.get('tax_type'),());done=payload.get('workflow_done',[])
    if not isinstance(done,list) or any(type(x) is not bool for x in done) or len(done)>len(steps):raise ValueError('وضعیت مراحل معتبر نیست.')
    if any(done[i] and not all(done[:i]) for i in range(len(done))):raise ValueError('مراحل باید به ترتیب تکمیل شوند.')
    return list(done)+[False]*(len(steps)-len(done))

