def step_guide(kind,index):
    guides=GUIDES.get(kind,())
    return guides[index] if 0<=index<len(guides) else ''

def period_bounds(year,month,period):
    from storage import month_last_day
    if period=='quarter':start=((month-1)//3)*3+1;end=start+2
    elif period=='year':start=1;end=12
    else:start=end=month
    return f'{year:04d}/{start:02d}/01',f'{year:04d}/{end:02d}/{month_last_day(year,end):02d}'

def case_review(payload):
    """Report missing recorded evidence, never infer a legal filing outcome."""
    findings=[]
    if not str(payload.get('due_date') or '').strip():findings.append('موعد تأییدشده هنوز ثبت نشده است.')
    if not str(payload.get('source') or '').strip():findings.append('منبع موعد یا نرخ ثبت نشده است.')
    if not str(payload.get('responsible') or '').strip():findings.append('مسئول پیگیری مشخص نشده است.')
    if payload.get('status') in ('submitted','completed'):
        if not str(payload.get('reference') or '').strip():findings.append('شماره پیگیری ثبت نشده است.')
        if not str(payload.get('submitted_date') or '').strip():findings.append('تاریخ ارسال ثبت نشده است.')
    if payload.get('paid_amount') and not str(payload.get('payment_date') or '').strip():findings.append('برای مبلغ پرداختی تاریخ پرداخت ثبت نشده است.')
    return findings
